<script setup lang="ts">
import { computed, onMounted, provide, ref } from "vue"; import { useRoute } from "vue-router"; import { listRepairs, type Repair } from "../api";
const route = useRoute(); const repair = ref<Repair | null>(null); provide("repair", repair); const title = computed(() => repair.value ? `${repair.value.brand} ${repair.value.model}` : "Reparacion"); onMounted(async () => { repair.value = (await listRepairs()).find((item) => item.id === route.params.id) ?? null; });
</script>
<template><section v-if="repair" class="customer-detail"><p class="breadcrumb"><RouterLink :to="{ name: 'repairs.list' }">Reparaciones</RouterLink> / {{ title }}</p><header><div><p class="eyebrow">Orden de reparacion</p><h1>{{ title }}</h1><span class="status-pill">{{ repair.status }}</span></div></header><nav class="tab-nav"><RouterLink :to="{ name: 'repairs.detail.general' }">General</RouterLink><RouterLink :to="{ name: 'repairs.detail.technical' }">Diagnostico</RouterLink><RouterLink :to="{ name: 'repairs.detail.quote' }">Presupuesto</RouterLink><RouterLink :to="{ name: 'repairs.detail.materials' }">Materiales</RouterLink><RouterLink :to="{ name: 'repairs.detail.history' }">Historial</RouterLink><RouterLink :to="{ name: 'repairs.detail.payments' }">Cobros</RouterLink><RouterLink :to="{ name: 'repairs.detail.chat' }">Mensajes</RouterLink></nav><RouterView /></section><p v-else class="empty">Cargando reparacion...</p></template>